import sys

def min_i(n, k, A):
    def prefix_sum(arr):
        return [sum(arr[:i+1]) for i in range(len(arr))]

    def binary_search(arr, target):
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    i = 0
    while True:
        if any(x >= k for x in A):
            return i
        A = prefix_sum([x - 1 for x in A])
        i += 1

